contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint am, uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount <= address(this).balance);
        require(address(this).balance - depositAmount >= am);

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore >= c.MinSum());
        require(balBefore >= am);

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || balAfter == balBefore - am);
    }

    receive() external payable {}
}

